-- GOOD_CHUKSAN_SEED_DB.sql
-- MEATOS Good Chuksan source-row staging schema + seed data

create table if not exists suppliers (
  supplier_id text primary key,
  supplier_name text not null,
  business_no text,
  manager text,
  phone text,
  active boolean not null default true,
  created_at timestamp not null default current_timestamp,
  updated_at timestamp not null default current_timestamp
);

create table if not exists product_import_batches (
  batch_id text primary key,
  supplier_id text not null references suppliers(supplier_id),
  source_file text not null,
  source_sheet text not null,
  source_printed_date text,
  expected_rows integer not null default 0,
  loaded_rows integer not null default 0,
  duplicate_name_groups integer not null default 0,
  source_column_count integer not null default 0,
  unit1_raw text,
  status text not null default 'awaiting_source_file',
  created_at timestamp not null default current_timestamp,
  updated_at timestamp not null default current_timestamp
);

create table if not exists product_source_rows (
  source_row_id text primary key,
  batch_id text not null references product_import_batches(batch_id),
  row_no integer not null,
  source_product_code text not null,
  source_product_name text not null,
  origin_raw text,
  grade_raw text,
  unit1_raw text,
  unit2_raw text,
  purchase_price numeric(12, 2) not null default 0,
  sales_price numeric(12, 2) not null default 0,
  major_category_code text,
  major_category_name text,
  middle_category_code text,
  middle_category_name text,
  minor_category_code text,
  minor_category_name text,
  product_class_code text,
  product_class_name text,
  cut_code text,
  cut_name text,
  import_type_code text,
  import_type_name text,
  normalized_name text,
  inferred_species text,
  inferred_storage_type text,
  mapping_status text not null default 'pending_review',
  review_status text not null default 'pending_review',
  mapped_product_id text,
  review_note text,
  is_duplicate boolean not null default false,
  is_cost_item boolean not null default false,
  duplicate_group_key text,
  created_at timestamp not null default current_timestamp,
  updated_at timestamp not null default current_timestamp
);

create table if not exists product_master (
  product_id text primary key,
  product_code text,
  standard_name text not null,
  category text,
  species text,
  part text,
  processing_type text,
  skin_type text,
  bone_type text,
  storage_type text,
  origin text,
  grade text,
  brand text,
  unit text,
  active boolean not null default true,
  created_at timestamp not null default current_timestamp,
  updated_at timestamp not null default current_timestamp
);

create table if not exists product_alias (
  alias_id text primary key,
  product_id text not null references product_master(product_id),
  raw_name text not null,
  normalized_name text not null,
  confidence integer not null default 100,
  verified boolean not null default false,
  use_count integer not null default 0,
  source_domain text,
  source_type text,
  active boolean not null default true,
  created_at timestamp not null default current_timestamp,
  updated_at timestamp not null default current_timestamp
);

create table if not exists product_mapping_review (
  review_id text primary key,
  source_row_id text not null references product_source_rows(source_row_id),
  mapped_product_id text references product_master(product_id),
  review_status text not null default 'pending_review',
  review_note text,
  reviewer text,
  created_at timestamp not null default current_timestamp,
  updated_at timestamp not null default current_timestamp
);

create index if not exists idx_product_source_rows_batch on product_source_rows(batch_id);
create index if not exists idx_product_source_rows_status on product_source_rows(mapping_status, review_status);
create index if not exists idx_product_source_rows_name on product_source_rows(source_product_name);
create index if not exists idx_product_alias_product on product_alias(product_id);
create index if not exists idx_product_mapping_review_status on product_mapping_review(review_status);



on conflict (source_row_id) do nothing;

-- The actual Excel source rows were imported without altering source_product_code or source_product_name.